INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(548554, 55779, 14453, '<td valign="top">It''s beautiful! Good light.</td>', 'It''s beautiful! Good light.', '2004-01-19 07:05:54.000000', NULL, 1),
(548558, 55587, 14453, '<td valign="top">What did you say to this buddy so he got that angry? Scary!!! <br/>It''s a very good picture, In bonus you captured the feeling of cold. Beautiful! 9.</td>', 'What did you say to this buddy so he got that angry? Scary!!! It''s a very good picture, In bonus you captured the feeling of cold. Beautiful! 9.', '2004-01-19 07:07:37.000000', NULL, 1),
(548571, 55781, 8643, '<td valign="top">Nice contrast and colouring but a straight horizon might be an improvement.</td>', 'Nice contrast and colouring but a straight horizon might be an improvement.', '2004-01-19 07:40:51.000000', NULL, 1),
(548572, 55707, 8643, '<td valign="top">Something to show the scale would habeen helpful - bullets or shells?</td>', 'Something to show the scale would habeen helpful - bullets or shells?', '2004-01-19 07:43:02.000000', NULL, 1),
(548577, 55501, 8643, '<td valign="top">Attractive view of Lancing College in its surroundings.</td>', 'Attractive view of Lancing College in its surroundings.', '2004-01-19 07:51:04.000000', NULL, 1),
(548578, 55774, 8643, '<td valign="top">This might be more effective without the flower in the foreground or with increased DoF so it is not quite so out of focus.</td>', 'This might be more effective without the flower in the foreground or with increased DoF so it is not quite so out of focus.', '2004-01-19 07:53:08.000000', NULL, 1),
(548580, 55747, 8643, '<td valign="top">Nice portrait, excellent control of detail in the shadow, great eyes!</td>', 'Nice portrait, excellent control of detail in the shadow, great eyes!', '2004-01-19 07:55:58.000000', NULL, 1),
(548582, 55424, 8139, '<td valign="top">Where leads this lovely rural path?<br/>Nice B/W, the space leaved to the sky , with the subtle gradations of the clouds, works well for me.</td>', 'Where leads this lovely rural path?Nice B/W, the space leaved to the sky , with the subtle gradations of the clouds, works well for me.', '2004-01-19 07:58:49.000000', NULL, 1),
(548583, 55774, 6130, '<td valign="top">Fantastic.</td>', 'Fantastic.', '2004-01-19 07:59:27.000000', NULL, 1),
(548584, 55522, 8643, '<td valign="top">Nice capture, glad he sat still for long enough!</td>', 'Nice capture, glad he sat still for long enough!', '2004-01-19 08:00:52.000000', NULL, 1),
(548585, 55501, 6130, '<td valign="top">I like the colors and everything in this.</td>', 'I like the colors and everything in this.', '2004-01-19 08:01:06.000000', NULL, 1),
(548586, 55822, 6130, '<td valign="top">Nice and very good.</td>', 'Nice and very good.', '2004-01-19 08:02:57.000000', NULL, 1),
(548592, 55789, 14614, '<td valign="top">Extra credit for the yellow border and background!  Good think you left room for the title and the articles! ;)<br/>Mask angle is interesting and highlights the top/hair.  I assume you found that more interesting than the mouth/chin (I think I would like to see more of those).   In all a great execution of the theme.</td>', 'Extra credit for the yellow border and background!  Good think you left room for the title and the articles! ;)Mask angle is interesting and highlights the top/hair.  I assume you found that more interesting than the mouth/chin (I think I would like to see more of those).   In all a great execution of the theme.', '2004-01-19 08:09:37.000000', NULL, 1),
(548593, 55706, 14614, '<td valign="top">WOW. You''ve captured an excellent expression.  The red headpieces and necklace frame the subject.  Sadly, part of the face/neck gets lost to the background.  The eye are wonderful.  Great execution of the theme</td>', 'WOW. You''ve captured an excellent expression.  The red headpieces and necklace frame the subject.  Sadly, part of the face/neck gets lost to the background.  The eye are wonderful.  Great execution of the theme', '2004-01-19 08:11:26.000000', NULL, 1),
(548597, 55718, 14614, '<td valign="top">Nicely composed and interesting ewers.  Would like a more interesting background.  They seem soft in some areas.</td>', 'Nicely composed and interesting ewers.  Would like a more interesting background.  They seem soft in some areas.', '2004-01-19 08:14:27.000000', NULL, 1),
(548598, 55360, 14614, '<td valign="top">Extra credit for the yellow/white border!  A bit more lighting on the bird would really make this shot pop. Good dof, interesting composition</td>', 'Extra credit for the yellow/white border!  A bit more lighting on the bird would really make this shot pop. Good dof, interesting composition', '2004-01-19 08:15:48.000000', NULL, 1),
(548606, 55399, 6008, '<td valign="top">Good shot! The composition is good, although I think I would have liked his feet in the shot so it didnt feel so incomplete. Very good texture and color, and nicely sharp.</td>', 'Good shot! The composition is good, although I think I would have liked his feet in the shot so it didnt feel so incomplete. Very good texture and color, and nicely sharp.', '2004-01-19 08:32:20.000000', NULL, 1),
(548610, 55501, 6008, '<td valign="top">It''s unfortunate about the overcast sky, but with the photograph only having a small amount I dont think it pulls away from the beauty of the shot all that much. I love the layered look of the shot. The water looks cold, the green looks very vibrant, the house/estate very stately, and the hazed town in the distance all adds up to a great shot.</td>', 'It''s unfortunate about the overcast sky, but with the photograph only having a small amount I dont think it pulls away from the beauty of the shot all that much. I love the layered look of the shot. The water looks cold, the green looks very vibrant, the house/estate very stately, and the hazed town in the distance all adds up to a great shot.', '2004-01-19 08:37:03.000000', NULL, 1),
(548616, 55483, 6008, '<td valign="top">I like the choice of angle you have used, being above the subject, as I think it shows his/her vulnerability a lot more than if you had gone down on their level. The expression on his/her face is good too. Looks very much like a shot that would have been featured in NG.</td>', 'I like the choice of angle you have used, being above the subject, as I think it shows his/her vulnerability a lot more than if you had gone down on their level. The expression on his/her face is good too. Looks very much like a shot that would have been featured in NG.', '2004-01-19 08:45:09.000000', NULL, 1),
(548620, 55242, 4493, '<td valign="top">Fabulous details. Great DOF and lighting. 10 -danny</td>', 'Fabulous details. Great DOF and lighting. 10 -danny', '2004-01-19 08:53:47.000000', NULL, 1),
(548622, 55522, 4493, '<td valign="top">I went out to shoot cardinals on Saturday and did not have much success. These guys are flighty little guys. You''re capture is wonderful. I love how it appears to have lighting from below. 9 -danny</td>', 'I went out to shoot cardinals on Saturday and did not have much success. These guys are flighty little guys. You''re capture is wonderful. I love how it appears to have lighting from below. 9 -danny', '2004-01-19 08:54:58.000000', NULL, 1),
(548625, 55818, 14614, '<td valign="top">Great face and pov.  hand on left distracts from an overall well done shot</td>', 'Great face and pov.  hand on left distracts from an overall well done shot', '2004-01-19 08:58:07.000000', NULL, 1),
(548627, 55775, 14614, '<td valign="top">Nicely composed.  Excellent background, interesting color.</td>', 'Nicely composed.  Excellent background, interesting color.', '2004-01-19 08:58:49.000000', NULL, 1),
(548628, 55716, 5792, '<td valign="top">Gee... I wonder where this was taken and who those beautiful people are? :)</td>', 'Gee... I wonder where this was taken and who those beautiful people are? :)', '2004-01-19 08:59:33.000000', NULL, 1),
(548631, 55114, 14614, '<td valign="top">Like the timing (to see the breath), would have liked less foreground and to see the whole back in the shot.  In general more of the bison and less of the surroundings</td>', 'Like the timing (to see the breath), would have liked less foreground and to see the whole back in the shot.  In general more of the bison and less of the surroundings', '2004-01-19 09:00:18.000000', NULL, 1),
(548633, 55776, 14614, '<td valign="top">Extra credit for the cover shot! You picture saves room for the NG title ;-)<br/>Nicely composed, interesting sky. An element that would show scale might be a good addition.</td>', 'Extra credit for the cover shot! You picture saves room for the NG title ;-)Nicely composed, interesting sky. An element that would show scale might be a good addition.', '2004-01-19 09:06:08.000000', NULL, 1),
(548637, 55819, 14614, '<td valign="top">Extra credit for the cover shot - got to leave room for the NG title ;-)<br/>Great expression on the animal, he''s a bit soft in the eye and neck.  Good dof in background</td>', 'Extra credit for the cover shot - got to leave room for the NG title ;-)Great expression on the animal, he''s a bit soft in the eye and neck.  Good dof in background', '2004-01-19 09:10:24.000000', NULL, 1),
(548638, 55769, 4517, '<td valign="top">Is this the grand hotel in Brighton?</td>', 'Is this the grand hotel in Brighton?', '2004-01-19 09:10:25.000000', NULL, 1),
(548640, 55643, 14614, '<td valign="top">Congrats on the cover shot!  Nice composition and dof.</td>', 'Congrats on the cover shot!  Nice composition and dof.', '2004-01-19 09:11:29.000000', NULL, 1),
(548641, 55605, 14614, '<td valign="top">Better lighting would have given this some needed punch.  Seems a bit soft.  Creative subject - unique idea from the shots I''ve seen so far</td>', 'Better lighting would have given this some needed punch.  Seems a bit soft.  Creative subject - unique idea from the shots I''ve seen so far', '2004-01-19 09:12:54.000000', NULL, 1),
(548645, 55507, 4517, '<td valign="top">This is excellent. Movement of the people makes this photo 10</td>', 'This is excellent. Movement of the people makes this photo 10', '2004-01-19 09:15:09.000000', NULL, 1),
(548646, 55053, 14614, '<td valign="top">Better lighting would help this shot - the rider gets lost in the background.  Subject meets the theme.  Perhaps focusing on either the horse or the rider - they''re competing for my attention</td>', 'Better lighting would help this shot - the rider gets lost in the background.  Subject meets the theme.  Perhaps focusing on either the horse or the rider - they''re competing for my attention', '2004-01-19 09:15:20.000000', NULL, 1),
(548647, 55759, 14614, '<td valign="top">I''ve never heard of this sea!  Great color pallet.  Main subject looks a little soft (not sure where the other animals are - unless you mean the coral)</td>', 'I''ve never heard of this sea!  Great color pallet.  Main subject looks a little soft (not sure where the other animals are - unless you mean the coral)', '2004-01-19 09:17:09.000000', NULL, 1),
(548648, 55671, 14614, '<td valign="top">Good composition and spraying water effect.  Too bad the sky is blown out upper right.  Fits the theme</td>', 'Good composition and spraying water effect.  Too bad the sky is blown out upper right.  Fits the theme', '2004-01-19 09:18:07.000000', NULL, 1),
(548649, 55782, 14614, '<td valign="top">Lot of detail in that title ;)   Strong subject well placed in the frame.  Small distraction of light area lower right.   Good detail in trunk and branches.</td>', 'Lot of detail in that title ;)   Strong subject well placed in the frame.  Small distraction of light area lower right.   Good detail in trunk and branches.', '2004-01-19 09:19:25.000000', NULL, 1),
(548651, 55695, 14614, '<td valign="top">Overall well done.  Would like to see less of the upper left.  Color pallet is good, nice lighting.  Would benefit from an element to show scale.</td>', 'Overall well done.  Would like to see less of the upper left.  Color pallet is good, nice lighting.  Would benefit from an element to show scale.', '2004-01-19 09:20:40.000000', NULL, 1),
(548652, 55804, 14614, '<td valign="top">I played around with an arrowhead too - couldn''t get mine to work but yours does.  Something about the blue background takes away from the image.  Perhaps a more natural locations?</td>', 'I played around with an arrowhead too - couldn''t get mine to work but yours does.  Something about the blue background takes away from the image.  Perhaps a more natural locations?', '2004-01-19 09:22:40.000000', NULL, 1),
(548654, 55420, 15129, '<td valign="top">Awesome, especially in regard to clarity and depth of field. Good luck.</td>', 'Awesome, especially in regard to clarity and depth of field. Good luck.', '2004-01-19 09:24:16.000000', NULL, 1),
(548655, 55629, 15129, '<td valign="top">Neat colors and composition, but it seems to be a bit out of focus.</td>', 'Neat colors and composition, but it seems to be a bit out of focus.', '2004-01-19 09:25:11.000000', NULL, 1),
(548657, 55807, 15129, '<td valign="top">Gorgeous. Great exposure.</td>', 'Gorgeous. Great exposure.', '2004-01-19 09:26:00.000000', NULL, 1),
(548658, 55114, 15129, '<td valign="top">Neat picture but I wish his hump hadn''t been "cut off".</td>', 'Neat picture but I wish his hump hadn''t been "cut off".', '2004-01-19 09:27:12.000000', NULL, 1),
(548660, 55746, 15129, '<td valign="top">Beautiful color and composition. Good luck.</td>', 'Beautiful color and composition. Good luck.', '2004-01-19 09:27:33.000000', NULL, 1),
(548661, 55507, 15129, '<td valign="top">Awesome street photography, blurring and perspective. I hope this gets "the blue". Good luck.</td>', 'Awesome street photography, blurring and perspective. I hope this gets "the blue". Good luck.', '2004-01-19 09:28:59.000000', NULL, 1),
(548663, 55752, 15129, '<td valign="top">Great close-up! (And made me laugh--thanks!)</td>', 'Great close-up! (And made me laugh--thanks!)', '2004-01-19 09:30:14.000000', NULL, 1),
(548665, 55522, 15129, '<td valign="top">I love this. Wonderful closeup and composition. Great effect with the snow blowing. Good luck.</td>', 'I love this. Wonderful closeup and composition. Great effect with the snow blowing. Good luck.', '2004-01-19 09:30:59.000000', NULL, 1),
(548668, 55053, 15129, '<td valign="top">Take my opinion for what it''s worth please ( you won''t get far) . . . but I''d have like to seen the rest of the horse''s muzzle--also have the picture exposed so we can see more of the rider. This would be tricky because of the close-up of the white horse and what seems to have been a low-light scene.</td>', 'Take my opinion for what it''s worth please ( you won''t get far) . . . but I''d have like to seen the rest of the horse''s muzzle--also have the picture exposed so we can see more of the rider. This would be tricky because of the close-up of the white horse and what seems to have been a low-light scene.', '2004-01-19 09:35:31.000000', NULL, 1),
(548670, 55683, 15129, '<td valign="top">Pretty picture and I love th color saturation, but the sky seems noisy or grainy.</td>', 'Pretty picture and I love th color saturation, but the sky seems noisy or grainy.', '2004-01-19 09:38:32.000000', NULL, 1),
(548673, 55471, 15129, '<td valign="top">Great wide angle, but a little out of focus and not enough "sparkle" in regard to the lights in the buildings (sorry for the untechnical term).</td>', 'Great wide angle, but a little out of focus and not enough "sparkle" in regard to the lights in the buildings (sorry for the untechnical term).', '2004-01-19 09:41:17.000000', NULL, 1),
(548674, 55541, 6668, '<td valign="top">wonderful capture, is that his breath you can see?..wow..nie shot.</td>', 'wonderful capture, is that his breath you can see?..wow..nie shot.', '2004-01-19 09:41:32.000000', NULL, 1),
(548675, 55541, 5491, '<td valign="top">Wow. Excellent photo!  I assume you must have cropped this down quite a bit but I think I might have left more empty space at the top left. I love the steam!</td>', 'Wow. Excellent photo!  I assume you must have cropped this down quite a bit but I think I might have left more empty space at the top left. I love the steam!', '2004-01-19 09:42:04.000000', NULL, 1),
(548677, 55789, 6668, '<td valign="top">I don''t personally care for the background in this shot, it makes the head appear as if it is floating in nowwhere and seems unnatural to me.   Interesting artifact though.</td>', 'I don''t personally care for the background in this shot, it makes the head appear as if it is floating in nowwhere and seems unnatural to me.   Interesting artifact though.', '2004-01-19 09:47:15.000000', NULL, 1),
(548680, 55803, 6668, '<td valign="top">I find the tree on the right hand side to be a bit destracting, also I dont care for the border only on two sides, makes the photo feel uneven to me.</td>', 'I find the tree on the right hand side to be a bit destracting, also I dont care for the border only on two sides, makes the photo feel uneven to me.', '2004-01-19 09:51:00.000000', NULL, 1),
(548681, 55721, 5491, '<td valign="top">This is a very good photo but I think the meaning of it is going to be lost on the average DPC voter.  Not many people are going to realize that those drugs are Fortovase and Zerit (I work for a pharmaceutical company). They might just think you threw some drugs on a map. 8</td>', 'This is a very good photo but I think the meaning of it is going to be lost on the average DPC voter.  Not many people are going to realize that those drugs are Fortovase and Zerit (I work for a pharmaceutical company). They might just think you threw some drugs on a map. 8', '2004-01-19 09:53:19.000000', NULL, 1),
(548682, 55230, 6668, '<td valign="top">Great action shot...nice work.</td>', 'Great action shot...nice work.', '2004-01-19 09:53:27.000000', NULL, 1),
(548683, 55744, 5491, '<td valign="top">Great idea but it looks like there''s some bad artifacting in that shot. It''s either that or grain. You might try not optimizing it quite as much when you save.</td>', 'Great idea but it looks like there''s some bad artifacting in that shot. It''s either that or grain. You might try not optimizing it quite as much when you save.', '2004-01-19 09:54:33.000000', NULL, 1),
(548685, 55818, 5491, '<td valign="top">Well I suppose being a prostrate ape is better than being a prostate ape! *rimshot*<br/> <br/>Great shot! I would like to see this one with the focus only on its face and the hands/arms blurred more.</td>', 'Well I suppose being a prostrate ape is better than being a prostate ape! *rimshot* Great shot! I would like to see this one with the focus only on its face and the hands/arms blurred more.', '2004-01-19 09:56:08.000000', NULL, 1),
(548686, 55360, 5491, '<td valign="top">Yep, totally an NG shot. It looks a bit washed out or undersaturated though. It''s not quite as crisp as it could be methinks.</td>', 'Yep, totally an NG shot. It looks a bit washed out or undersaturated though. It''s not quite as crisp as it could be methinks.', '2004-01-19 09:57:53.000000', NULL, 1),
(548687, 55771, 6668, '<td valign="top">nice shot...I love the colors..good luck in the challenge.</td>', 'nice shot...I love the colors..good luck in the challenge.', '2004-01-19 09:59:08.000000', NULL, 1),
(548688, 55471, 6668, '<td valign="top">That is a gorgous cityscape shot, such beatiful lights against the black sky, the border you have used works well here too. nice work.  Good luck in the challenge. 10</td>', 'That is a gorgous cityscape shot, such beatiful lights against the black sky, the border you have used works well here too. nice work.  Good luck in the challenge. 10', '2004-01-19 10:03:14.000000', NULL, 1),
(548690, 55483, 215, '<td valign="top">Probably would have burned the oranges a bit, but otherwise very good.</td>', 'Probably would have burned the oranges a bit, but otherwise very good.', '2004-01-19 10:03:47.000000', NULL, 1),
(548691, 55242, 6668, '<td valign="top">too bad his neck is cropped on on the top.</td>', 'too bad his neck is cropped on on the top.', '2004-01-19 10:04:02.000000', NULL, 1),
(548692, 55587, 10978, '<td valign="top">WOW this is a great shot, it would be perfect if it did not have that reflection from the glass on the right side, but then again if the glass was not there you would have been desert  LOL so great shot ...9</td>', 'WOW this is a great shot, it would be perfect if it did not have that reflection from the glass on the right side, but then again if the glass was not there you would have been desert  LOL so great shot ...9', '2004-01-19 10:05:53.000000', NULL, 1),
(548693, 55787, 215, '<td valign="top">Purple fridging appearing at the top of the photo, where the sky has been overexposed and has no detail. I think if you shot this at about -1/3 or -2/3 EV, you can bring some details back.</td>', 'Purple fridging appearing at the top of the photo, where the sky has been overexposed and has no detail. I think if you shot this at about -1/3 or -2/3 EV, you can bring some details back.', '2004-01-19 10:05:57.000000', NULL, 1),
(548695, 55762, 215, '<td valign="top">Crop to focus on the subject and mitigate the effects of the fense in the background. Also, probably should have shot it maybe +2/3 or +1 EV to get the snow to be pure white (or fix in Photoshop, of course).</td>', 'Crop to focus on the subject and mitigate the effects of the fense in the background. Also, probably should have shot it maybe +2/3 or +1 EV to get the snow to be pure white (or fix in Photoshop, of course).', '2004-01-19 10:07:21.000000', NULL, 1),
(548700, 55499, 215, '<td valign="top">Try a smaller aperture to bring the foreground back into focus as well to achieve a even better effect.</td>', 'Try a smaller aperture to bring the foreground back into focus as well to achieve a even better effect.', '2004-01-19 10:12:09.000000', NULL, 1),
(548702, 55399, 215, '<td valign="top">If only the feet of the animal were captured as well (so in effect shifting the whole frame down to cut the tree and include the feet)...</td>', 'If only the feet of the animal were captured as well (so in effect shifting the whole frame down to cut the tree and include the feet)...', '2004-01-19 10:13:41.000000', NULL, 1),
(548704, 55418, 215, '<td valign="top">I think if the footprints were of bare feet, that would have a even better effect.</td>', 'I think if the footprints were of bare feet, that would have a even better effect.', '2004-01-19 10:14:35.000000', NULL, 1),
(548716, 55814, 14614, '<td valign="top">Most definately NG.  Like the 50/50 composition but not sure about the white (great for contrast but doesn''t add interest) Colors on the cheek made the composition complete.</td>', 'Most definately NG.  Like the 50/50 composition but not sure about the white (great for contrast but doesn''t add interest) Colors on the cheek made the composition complete.', '2004-01-19 10:29:25.000000', NULL, 1),
(548717, 55716, 14614, '<td valign="top">Creative idea that works.  Good use of dof.  Didn''t know NG photographers shot behind a fence? ;-)</td>', 'Creative idea that works.  Good use of dof.  Didn''t know NG photographers shot behind a fence? ;-)', '2004-01-19 10:30:54.000000', NULL, 1),
(548719, 55363, 14614, '<td valign="top">Moody.  I''d like a subject in the shot (tree too far to right to be it) to add interest to your fog.</td>', 'Moody.  I''d like a subject in the shot (tree too far to right to be it) to add interest to your fog.', '2004-01-19 10:35:01.000000', NULL, 1),
(548720, 55701, 327, '<td valign="top">One of favorite rivers and have fished it many times. Sure gets cold around Hell''s Canyon and windy too. Nice sunset.</td>', 'One of favorite rivers and have fished it many times. Sure gets cold around Hell''s Canyon and windy too. Nice sunset.', '2004-01-19 10:36:55.000000', NULL, 1),
(548722, 55752, 327, '<td valign="top">These are amazing looking cows. Wooly beast.</td>', 'These are amazing looking cows. Wooly beast.', '2004-01-19 10:39:12.000000', NULL, 1),
(548723, 55564, 14614, '<td valign="top">A good subject but I can''t see it very well.  Suggest more light and filling the frame with this guy.</td>', 'A good subject but I can''t see it very well.  Suggest more light and filling the frame with this guy.', '2004-01-19 10:40:49.000000', NULL, 1),
(548724, 55814, 327, '<td valign="top">I think this is perfect for the challenge and the colors are nice. I do think that the white background takes away from the mask. It''s so stark that it washes out the mask causing everything to look over exposed. It''s a good entry.</td>', 'I think this is perfect for the challenge and the colors are nice. I do think that the white background takes away from the mask. It''s so stark that it washes out the mask causing everything to look over exposed. It''s a good entry.', '2004-01-19 10:41:10.000000', NULL, 1),
(548725, 55779, 14614, '<td valign="top">Intense color and sharp eye.  Nicely composed NG shot.</td>', 'Intense color and sharp eye.  Nicely composed NG shot.', '2004-01-19 10:41:30.000000', NULL, 1),
(548727, 55643, 327, '<td valign="top">Nice entry and nicely cropped. It appears a little over exposed and the colors are somewhat washed out [flat]. I do love these old trees and their expressive roots. Very mysterious looking trees.</td>', 'Nice entry and nicely cropped. It appears a little over exposed and the colors are somewhat washed out [flat]. I do love these old trees and their expressive roots. Very mysterious looking trees.', '2004-01-19 10:42:58.000000', NULL, 1),
