(549275, 55360, 806, '<td valign="top">this is a nice shot, but somehow lacks contrast. seems too dim/gray scale.</td>', 'this is a nice shot, but somehow lacks contrast. seems too dim/gray scale.', '2004-01-19 16:47:58.000000', NULL, 1),
(549276, 54901, 806, '<td valign="top">isn''t this pretty! reminds me of some of my favorite New England pond spots. the dof is perfectly done to draw you into the scene.</td>', 'isn''t this pretty! reminds me of some of my favorite New England pond spots. the dof is perfectly done to draw you into the scene.', '2004-01-19 16:49:27.000000', NULL, 1),
(549277, 55316, 14614, '<td valign="top">Crisp blacks and whites artistically done.</td>', 'Crisp blacks and whites artistically done.', '2004-01-19 16:49:32.000000', NULL, 1),
(549280, 55752, 806, '<td valign="top">nice shot. love the framing and close up.</td>', 'nice shot. love the framing and close up.', '2004-01-19 16:50:35.000000', NULL, 1),
(549281, 55774, 14614, '<td valign="top">You show just enough of the little girl to connect us with her.  Greenery in the foreground distracts from your cute subject.</td>', 'You show just enough of the little girl to connect us with her.  Greenery in the foreground distracts from your cute subject.', '2004-01-19 16:50:40.000000', NULL, 1),
