(549286, 55737, 14614, '<td valign="top">The bright pick of your finger and nail detract from your main subject a bit (they''re as big as the turtle and thus fight for attention as an important element)  The turtle is quite interesting and I''d like to see him larger and alone in the shot</td>', 'The bright pick of your finger and nail detract from your main subject a bit (they''re as big as the turtle and thus fight for attention as an important element)  The turtle is quite interesting and I''d like to see him larger and alone in the shot', '2004-01-19 16:52:33.000000', NULL, 1),
(549288, 55725, 10720, '<td valign="top">Good choice for the theme</td>', 'Good choice for the theme', '2004-01-19 16:53:09.000000', NULL, 1),
(549289, 55771, 806, '<td valign="top">excellent shot! great detail, colors, framing, .. could get his foot in there a bit more, but I really like this.<br/></td>', 'excellent shot! great detail, colors, framing, .. could get his foot in there a bit more, but I really like this.', '2004-01-19 16:53:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(549290, 55483, 10720, '<td valign="top">Nice bright colors, good expression too. Even got all of his foot in.</td>', 'Nice bright colors, good expression too. Even got all of his foot in.', '2004-01-19 16:53:50.000000', NULL, 1),
(549292, 55501, 14614, '<td valign="top">Your composition keeps leading my eye further into your photo.  Nice colors, too.  I''d like to know, per NG, which river - Where am I?</td>', 'Your composition keeps leading my eye further into your photo.  Nice colors, too.  I''d like to know, per NG, which river - Where am I?', '2004-01-19 16:53:57.000000', NULL, 1),
(549294, 55696, 16318, '<td valign="top">I like this but I wish I could see the face better.</td>', 'I like this but I wish I could see the face better.', '2004-01-19 16:55:20.000000', NULL, 1),
(549295, 55640, 14614, '<td valign="top">Well done. great colors, nice dof, fish cooperated and are in excellent spots of the frame.  In the title you''ve begun to tell the story (and you told me what I''m looking at)  can''t ask any more.</td>', 'Well done. great colors, nice dof, fish cooperated and are in excellent spots of the frame.  In the title you''ve begun to tell the story (and you told me what I''m looking at)  can''t ask any more.', '2004-01-19 16:55:36.000000', NULL, 1),
(549296, 55683, 14614, '<td valign="top">Not sure what that think in just right of center (should be cloned out?)  Otherwise nice composition.</td>', 'Not sure what that think in just right of center (should be cloned out?)  Otherwise nice composition.', '2004-01-19 16:56:44.000000', NULL, 1),
(549298, 55536, 16318, '<td valign="top">I can feel the warmth of the tea and taste the cookies!</td>', 'I can feel the warmth of the tea and taste the cookies!', '2004-01-19 16:57:21.000000', NULL, 1),
(549299, 55822, 14614, '<td valign="top">Liked that your title tells me where I am. Soft colors make the shot''s layers interesting and restful.</td>', 'Liked that your title tells me where I am. Soft colors make the shot''s layers interesting and restful.', '2004-01-19 16:57:31.000000', NULL, 1),
