(549321, 55717, 1779, '<td valign="top">great lighting and composition. shame about the leaf...<br/> <br/>:)</td>', 'great lighting and composition. shame about the leaf... :)', '2004-01-19 17:23:07.000000', NULL, 1),
(549322, 55734, 806, '<td valign="top">bright light against the white feathers is a tough situation that you handled well here. you can even see the eyes in the swans - which usually get lost in the dark markings around the eyes.<br/>nice going!</td>', 'bright light against the white feathers is a tough situation that you handled well here. you can even see the eyes in the swans - which usually get lost in the dark markings around the eyes.nice going!', '2004-01-19 17:23:18.000000', NULL, 1),
