(549324, 55721, 806, '<td valign="top">great message. nicely done.</td>', 'great message. nicely done.', '2004-01-19 17:25:51.000000', NULL, 1),
(549325, 55564, 806, '<td valign="top">needs to be a bit brighter,. maybe better contrast..</td>', 'needs to be a bit brighter,. maybe better contrast..', '2004-01-19 17:26:40.000000', NULL, 1),
