(549339, 55471, 215, '<td valign="top">The overall scene is a little too dark. I think if you had exposed it longer the effect would be much better.</td>', 'The overall scene is a little too dark. I think if you had exposed it longer the effect would be much better.', '2004-01-19 17:37:24.000000', NULL, 1),
(549340, 55782, 806, '<td valign="top">a wide angle would do wonders for this shot... would accentuate the wide circumferance tooted in the title. great colors saturation.</td>', 'a wide angle would do wonders for this shot... would accentuate the wide circumferance tooted in the title. great colors saturation.', '2004-01-19 17:38:10.000000', NULL, 1),
