(550089, 55694, 8139, '<td valign="top">Very nice effect. Like a solarisation. Curious to look to post processing description .</td>', 'Very nice effect. Like a solarisation. Curious to look to post processing description .', '2004-01-20 08:53:06.000000', NULL, 1),
(550097, 55706, 8139, '<td valign="top">At first look, seems to be a real ethnic photo. Nice.</td>', 'At first look, seems to be a real ethnic photo. Nice.', '2004-01-20 08:55:02.000000', NULL, 1),
(550099, 55359, 8139, '<td valign="top">Beautiful colors and mood.</td>', 'Beautiful colors and mood.', '2004-01-20 08:56:01.000000', NULL, 1),
(550114, 55818, 13534, '<td valign="top">Awesome perspective!</td>', 'Awesome perspective!', '2004-01-20 09:03:41.000000', NULL, 1),
(550116, 55747, 656, '<td valign="top">I like this shot a lot, very subtle lighting.  Almost feel it could do with a bit of fill flash on the left to bring out some more of the hair, but that might blow everything out.  If you could have dodged/ burned it or used flash to bring out some more eye catchlight that would have strengthed it some more.  A great capture as is and a very simple, strong composition without the background clutter.</td>', 'I like this shot a lot, very subtle lighting.  Almost feel it could do with a bit of fill flash on the left to bring out some more of the hair, but that might blow everything out.  If you could have dodged/ burned it or used flash to bring out some more eye catchlight that would have strengthed it some more.  A great capture as is and a very simple, strong composition without the background clutter.', '2004-01-20 09:04:10.000000', NULL, 1),
(550117, 55541, 8139, '<td valign="top">Very expressive , good lighting, sharp...shame the photo is a bit small, why not use the 640 pix allowed?</td>', 'Very expressive , good lighting, sharp...shame the photo is a bit small, why not use the 640 pix allowed?', '2004-01-20 09:07:29.000000', NULL, 1),
