INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(550150, 55587, 12654, '<td valign="top">Awesome pic - excelent!!!!!!!!!</td>', 'Awesome pic - excelent!!!!!!!!!', '2004-01-20 09:51:13.000000', NULL, 1),
(550164, 55807, 12654, '<td valign="top">Superb - at a loss for words</td>', 'Superb - at a loss for words', '2004-01-20 10:05:30.000000', NULL, 1),
(550179, 55483, 5158, '<td valign="top">Great image: love the composition and colour. Also well cropped.<br/>One of my very favorits. Good luck to you!</td>', 'Great image: love the composition and colour. Also well cropped.One of my very favorits. Good luck to you!', '2004-01-20 10:16:42.000000', NULL, 1),
(550180, 55574, 5158, '<td valign="top">Even without the current cahllenge subject everybody would associate this image with NG! Great pose of the kitty and very crisp. One of my favorits. Good luck.</td>', 'Even without the current cahllenge subject everybody would associate this image with NG! Great pose of the kitty and very crisp. One of my favorits. Good luck.', '2004-01-20 10:18:10.000000', NULL, 1),
(550181, 55738, 13136, '<td valign="top">This shot looks a bit odd with the light spot in the upper right. It''s a bit confusing, but nice.</td>', 'This shot looks a bit odd with the light spot in the upper right. It''s a bit confusing, but nice.', '2004-01-20 10:18:10.000000', NULL, 1),
(550183, 55285, 5822, '<td valign="top">DOF is too narrow to really appreciate this image, as most of it appears out of focus.</td>', 'DOF is too narrow to really appreciate this image, as most of it appears out of focus.', '2004-01-20 10:18:27.000000', NULL, 1),
(550189, 55694, 13136, '<td valign="top">Unique color and shading. Beautiful shot.</td>', 'Unique color and shading. Beautiful shot.', '2004-01-20 10:21:15.000000', NULL, 1),
(550190, 55640, 5158, '<td valign="top">I like the light and the colour very much. Only the balance between the fishs and the rocks is a little off. Maybe only showing just one fish would have been better.<br/>Still, I hope you do well with this wonderfull image.</td>', 'I like the light and the colour very much. Only the balance between the fishs and the rocks is a little off. Maybe only showing just one fish would have been better.Still, I hope you do well with this wonderfull image.', '2004-01-20 10:21:18.000000', NULL, 1),
(550196, 55759, 5158, '<td valign="top">Nice use of DOF in this colourfull image. It''s a little bright though and also too grainy. Otherwise well composed and captured.</td>', 'Nice use of DOF in this colourfull image. It''s a little bright though and also too grainy. Otherwise well composed and captured.', '2004-01-20 10:22:58.000000', NULL, 1),
(550200, 55816, 13136, '<td valign="top">Nice picture. The tilt does not work for me here.</td>', 'Nice picture. The tilt does not work for me here.', '2004-01-20 10:24:30.000000', NULL, 1),
(550201, 55522, 5158, '<td valign="top">That''s areal beauty! Like the colour, crispness and the snowflaks on the bird as well as on the background. I can feel the coldness! Good luck to you.</td>', 'That''s areal beauty! Like the colour, crispness and the snowflaks on the bird as well as on the background. I can feel the coldness! Good luck to you.', '2004-01-20 10:24:35.000000', NULL, 1),
(550202, 55789, 5822, '<td valign="top">Meets the challenge theme well, but the angle you''ve shot your subject in seems odd. It''s also placed in the frame awkwardly.  The yellow border is not necessary except for cover pages.</td>', 'Meets the challenge theme well, but the angle you''ve shot your subject in seems odd. It''s also placed in the frame awkwardly.  The yellow border is not necessary except for cover pages.', '2004-01-20 10:25:38.000000', NULL, 1),
(550219, 55587, 12802, '<td valign="top">Very nice shot, very clear (he needs his teeth cleaned, not that I''m volunteering!) the colours of his coat are really good too! The added steam coming from his mouth is good.<br/> <br/>Think I would have liked to have seen more of his body, if that would have been too difficult, maybe more of his paws holding the meat.  Alos, sharpening it up a little would have brought out more detail, especially in his face.  7</td>', 'Very nice shot, very clear (he needs his teeth cleaned, not that I''m volunteering!) the colours of his coat are really good too! The added steam coming from his mouth is good. Think I would have liked to have seen more of his body, if that would have been too difficult, maybe more of his paws holding the meat.  Alos, sharpening it up a little would have brought out more detail, especially in his face.  7', '2004-01-20 10:37:04.000000', NULL, 1),
(550258, 55242, 8367, '<td valign="top">Beautiful capture. The feathers (?) on the head and neck look like velvet.<br/>(I don''t see pink on my monitor...orange tones.)</td>', 'Beautiful capture. The feathers (?) on the head and neck look like velvet.(I don''t see pink on my monitor...orange tones.)', '2004-01-20 10:53:38.000000', NULL, 1),
(550263, 55209, 11793, '<td valign="top">stunning.<br/> <br/>going back through my votes - i choose this as the winner</td>', 'stunning. going back through my votes - i choose this as the winner', '2004-01-20 10:56:23.000000', NULL, 1),
(550265, 55747, 11793, '<td valign="top">a glimmer in the eyes, and this is perfect...<br/> <br/>te overexposed areas give definition to the dark subject.  eyes are a bit on the dark side, but that glimmer would fix it i think.<br/> <br/>my choose for 2nd place<br/></td>', 'a glimmer in the eyes, and this is perfect... te overexposed areas give definition to the dark subject.  eyes are a bit on the dark side, but that glimmer would fix it i think. my choose for 2nd place', '2004-01-20 10:57:29.000000', NULL, 1),
(550269, 55522, 11793, '<td valign="top">what i like best about this compared to alot of the other animal shots, is it didnt come from a zoo or an aquarium, but is actually an animal in its real habitat.  making this much a national geogrpahic shot in my mind.  good luck</td>', 'what i like best about this compared to alot of the other animal shots, is it didnt come from a zoo or an aquarium, but is actually an animal in its real habitat.  making this much a national geogrpahic shot in my mind.  good luck', '2004-01-20 10:59:15.000000', NULL, 1),
(550272, 55640, 8682, '<td valign="top">Beatiful fishes! I really like the colours</td>', 'Beatiful fishes! I really like the colours', '2004-01-20 11:02:52.000000', NULL, 1),
(550273, 54987, 8682, '<td valign="top">Good use of the reflection on the water. Beatiful colours</td>', 'Good use of the reflection on the water. Beatiful colours', '2004-01-20 11:03:35.000000', NULL, 1),
(550276, 55666, 8682, '<td valign="top">I really love the use of duotones. I think it was a fantastic choice that gives to your image more interest.</td>', 'I really love the use of duotones. I think it was a fantastic choice that gives to your image more interest.', '2004-01-20 11:04:15.000000', NULL, 1),
(550277, 55671, 8682, '<td valign="top">Fantastic water shot!!!!!8</td>', 'Fantastic water shot!!!!!8', '2004-01-20 11:04:35.000000', NULL, 1),
(550278, 55483, 8682, '<td valign="top">Beatiful portrait! The composition and colours are very beatiful, too.</td>', 'Beatiful portrait! The composition and colours are very beatiful, too.', '2004-01-20 11:05:07.000000', NULL, 1),
(550280, 55523, 8682, '<td valign="top">Beatiful image. Perhaps, the shadow is distracting the attention.</td>', 'Beatiful image. Perhaps, the shadow is distracting the attention.', '2004-01-20 11:06:15.000000', NULL, 1),
(550282, 55574, 8682, '<td valign="top">Fantastic shot! Really well-focussed.</td>', 'Fantastic shot! Really well-focussed.', '2004-01-20 11:07:11.000000', NULL, 1),
(550283, 55778, 8682, '<td valign="top">Fantastic focus.</td>', 'Fantastic focus.', '2004-01-20 11:07:43.000000', NULL, 1),
(550286, 55522, 12448, '<td valign="top">Brrrrr, I get cold looking at this, excellent shot.  The motion of the snow, the resolute look of the bird, very well done.  I would have cropped just a tad tighter on the bottom so there is a little less of the bar he''s holding onto in the shot.  Just below the tail feathers :)  A 9</td>', 'Brrrrr, I get cold looking at this, excellent shot.  The motion of the snow, the resolute look of the bird, very well done.  I would have cropped just a tad tighter on the bottom so there is a little less of the bar he''s holding onto in the shot.  Just below the tail feathers :)  A 9', '2004-01-20 11:10:19.000000', NULL, 1),
(550288, 55671, 12448, '<td valign="top">This is beautiful!  I love the action and motion of the water, the lush green on the rocks and the composition is well done.  The only distracting thing to me is the rock poking in on the right side bottom, putting my paper up there to crop it out and the shot really comes alive for me.  Well done!  A 9</td>', 'This is beautiful!  I love the action and motion of the water, the lush green on the rocks and the composition is well done.  The only distracting thing to me is the rock poking in on the right side bottom, putting my paper up there to crop it out and the shot really comes alive for me.  Well done!  A 9', '2004-01-20 11:11:48.000000', NULL, 1),
(550289, 55587, 8682, '<td valign="top">It´s a fantastic shot!</td>', 'It´s a fantastic shot!', '2004-01-20 11:12:13.000000', NULL, 1),
(550292, 55218, 12448, '<td valign="top">Oh so close to my home of Montana!  I love this shot.  The mountains, the snow, the line of trees in the front to offer an starting point.  The clouds are awesome, the line of grey going through would have made a perfect top to me.  The blue sky is beautiful (really reminds me of home) but in this shot it pulls me away from the rest of the shot.  I put a paper up and set it just above the grey line of clouds and what a difference.  A 9</td>', 'Oh so close to my home of Montana!  I love this shot.  The mountains, the snow, the line of trees in the front to offer an starting point.  The clouds are awesome, the line of grey going through would have made a perfect top to me.  The blue sky is beautiful (really reminds me of home) but in this shot it pulls me away from the rest of the shot.  I put a paper up and set it just above the grey line of clouds and what a difference.  A 9', '2004-01-20 11:14:04.000000', NULL, 1),
(550294, 55364, 12448, '<td valign="top">This is a front cover shot if I ever saw one.  It''s missing the border though, LOL!  Seriously, this is a wonderful shot, really takes me back to the covers of NG and the lighting is well done, the shadows are perfect.  The only thing that bugs me just a tad is the left side, where the ear(?) is.  Would like to either see it all or take it out completely.  A 9</td>', 'This is a front cover shot if I ever saw one.  It''s missing the border though, LOL!  Seriously, this is a wonderful shot, really takes me back to the covers of NG and the lighting is well done, the shadows are perfect.  The only thing that bugs me just a tad is the left side, where the ear(?) is.  Would like to either see it all or take it out completely.  A 9', '2004-01-20 11:16:25.000000', NULL, 1),
(550299, 55496, 5822, '<td valign="top">I like the effect of the darker underside of the petals contrasted with the brigher sky and I"m glad you didn''t use any fill flash.</td>', 'I like the effect of the darker underside of the petals contrasted with the brigher sky and I"m glad you didn''t use any fill flash.', '2004-01-20 11:20:12.000000', NULL, 1),
(550308, 55666, 5822, '<td valign="top">Great shot!  The composition and cropping (if any) are wonderful and the tones and contrast excellent!  You really get a  "crowding in" feeling here without the image being too busy.  Fits the challenge theme very well.</td>', 'Great shot!  The composition and cropping (if any) are wonderful and the tones and contrast excellent!  You really get a  "crowding in" feeling here without the image being too busy.  Fits the challenge theme very well.', '2004-01-20 11:25:18.000000', NULL, 1),
