(550380, 55242, 7291, '<td valign="top">WOW!!!  The focus and detail is amazing.  Great choice of crop also. - 10</td>', 'WOW!!!  The focus and detail is amazing.  Great choice of crop also. - 10', '2004-01-20 12:08:21.000000', NULL, 1),
(550384, 54901, 15768, '<td valign="top">Beautiful... The greatest challenge to me was always to capture haze on a camera and make it look as good as it does in real life. Suggestion: Gaussian blur the top half until you get a uniform gradient of colour; the slight detail is somewhat distracting</td>', 'Beautiful... The greatest challenge to me was always to capture haze on a camera and make it look as good as it does in real life. Suggestion: Gaussian blur the top half until you get a uniform gradient of colour; the slight detail is somewhat distracting', '2004-01-20 12:10:55.000000', NULL, 1),
(550385, 55669, 16216, '<td valign="top">This has Great definition and Subject is amazing.. Great work</td>', 'This has Great definition and Subject is amazing.. Great work', '2004-01-20 12:11:07.000000', NULL, 1),
