(550403, 55747, 7291, '<td valign="top">Fantastic!  How did you manage that lighting?  I''m sure that required a pretty slow shutter speed, but yet nothing is blured.  Very impressive. - 10</td>', 'Fantastic!  How did you manage that lighting?  I''m sure that required a pretty slow shutter speed, but yet nothing is blured.  Very impressive. - 10', '2004-01-20 12:17:35.000000', NULL, 1),
(550407, 55757, 7291, '<td valign="top">I LOVE the expression!!!</td>', 'I LOVE the expression!!!', '2004-01-20 12:18:19.000000', NULL, 1),
