(550909, 55725, 12061, '<td valign="top">I''d say loosen it on the border a bit, its a little clunky. The image is great, DOF great, and I love the colors! nice work</td>', 'I''d say loosen it on the border a bit, its a little clunky. The image is great, DOF great, and I love the colors! nice work', '2004-01-20 19:43:23.000000', NULL, 1),
(550910, 55249, 12061, '<td valign="top">something about the color balance (white balance) on this isn''t working for me. The tones of purple/red are a little too powerful. Excellent subject, nice and sharp, overall looks great. nice work.</td>', 'something about the color balance (white balance) on this isn''t working for me. The tones of purple/red are a little too powerful. Excellent subject, nice and sharp, overall looks great. nice work.', '2004-01-20 19:44:28.000000', NULL, 1),
(550911, 55420, 12061, '<td valign="top">beautiful!! The dof and sharpness of this image is excellent - I love this one!</td>', 'beautiful!! The dof and sharpness of this image is excellent - I love this one!', '2004-01-20 19:46:24.000000', NULL, 1),
(550915, 55771, 14476, '<td valign="top">The first (and second) time I saw this, I thought you might have used Pshop stuff.  When I realized it was a creature - well disguised - it went from a 9 to a 10</td>', 'The first (and second) time I saw this, I thought you might have used Pshop stuff.  When I realized it was a creature - well disguised - it went from a 9 to a 10', '2004-01-20 19:56:47.000000', NULL, 1),
