(550919, 55747, 14476, '<td valign="top">The expression on this guy, plus the fine mood of the image rates (in my book) a 9.  Really, really nice.</td>', 'The expression on this guy, plus the fine mood of the image rates (in my book) a 9.  Really, really nice.', '2004-01-20 19:58:53.000000', NULL, 1),
(550921, 55756, 14476, '<td valign="top">I love the beauty of this animal - as you say, "greeting the sun."  If the contrasts, or lights vs darks were slightly different it would be a 10, but in my estimation, the photo is still well worth a 9.</td>', 'I love the beauty of this animal - as you say, "greeting the sun."  If the contrasts, or lights vs darks were slightly different it would be a 10, but in my estimation, the photo is still well worth a 9.', '2004-01-20 20:00:53.000000', NULL, 1),
(550922, 55536, 14476, '<td valign="top">This is a splendid frontier type image.  I hope you are related to this delightful person.  It''s a lovely picture portraying a gentle person.  8</td>', 'This is a splendid frontier type image.  I hope you are related to this delightful person.  It''s a lovely picture portraying a gentle person.  8', '2004-01-20 20:02:43.000000', NULL, 1),
(550924, 55541, 14476, '<td valign="top">Everyone says this challenge is a difficult one to score.  This picture is another splendid representation of nature with good detail, bringing us almost to the level of the bird being presented.   My 8 may go up.</td>', 'Everyone says this challenge is a difficult one to score.  This picture is another splendid representation of nature with good detail, bringing us almost to the level of the bird being presented.   My 8 may go up.', '2004-01-20 20:05:24.000000', NULL, 1),
(550926, 55567, 14476, '<td valign="top">This may or may not ever make it into National Georgraphic, but it is beautifully photographed and you are to be complimented on the entry.</td>', 'This may or may not ever make it into National Georgraphic, but it is beautifully photographed and you are to be complimented on the entry.', '2004-01-20 20:06:37.000000', NULL, 1),
(550928, 55797, 14476, '<td valign="top">Love your bobcat, with he was slightly more in focus.  His expression alone, however, is well worth entry in this challenge.  Easily a 7 - may be back.</td>', 'Love your bobcat, with he was slightly more in focus.  His expression alone, however, is well worth entry in this challenge.  Easily a 7 - may be back.', '2004-01-20 20:08:23.000000', NULL, 1),
(550929, 55364, 14476, '<td valign="top">One of the "non-living" entries that really caught my attention!  Beautifully photographed, and I would read every page of an article that told more about this pictured item.  Well done.</td>', 'One of the "non-living" entries that really caught my attention!  Beautifully photographed, and I would read every page of an article that told more about this pictured item.  Well done.', '2004-01-20 20:09:48.000000', NULL, 1),
(550948, 55587, 16374, '<td valign="top">WOW!!!!</td>', 'WOW!!!!', '2004-01-20 20:45:01.000000', NULL, 1),
(550967, 55242, 7467, '<td valign="top">Beautiful... a very unique color.</td>', 'Beautiful... a very unique color.', '2004-01-20 21:28:17.000000', NULL, 1),
(550969, 55587, 7467, '<td valign="top">Bet you were glad he was in some type of "cage", he looks very serious. Nice shot.</td>', 'Bet you were glad he was in some type of "cage", he looks very serious. Nice shot.', '2004-01-20 21:29:05.000000', NULL, 1),
(550971, 55818, 7467, '<td valign="top">Nice picture, very unique angle.</td>', 'Nice picture, very unique angle.', '2004-01-20 21:29:38.000000', NULL, 1),
(550972, 55701, 7467, '<td valign="top">Great sunset, looks like it is on fire.</td>', 'Great sunset, looks like it is on fire.', '2004-01-20 21:30:01.000000', NULL, 1),
(550976, 55541, 7467, '<td valign="top">Nice action and hot breath.. neat effect.</td>', 'Nice action and hot breath.. neat effect.', '2004-01-20 21:30:33.000000', NULL, 1),
(550978, 55694, 7467, '<td valign="top">I really like this... it is almost sur-real. Nice...</td>', 'I really like this... it is almost sur-real. Nice...', '2004-01-20 21:31:12.000000', NULL, 1),
(550981, 55771, 7467, '<td valign="top">Very sharp, great colors. What is going on in the lower left portion of the critter? What is that sharp dividing line? oh... Must be his leg at a 90 degree angle.</td>', 'Very sharp, great colors. What is going on in the lower left portion of the critter? What is that sharp dividing line? oh... Must be his leg at a 90 degree angle.', '2004-01-20 21:32:57.000000', NULL, 1),
(550982, 55420, 7467, '<td valign="top">Good title, nice colors, too bad the background is not a little more contrasting. Still a very nice shot.</td>', 'Good title, nice colors, too bad the background is not a little more contrasting. Still a very nice shot.', '2004-01-20 21:33:44.000000', NULL, 1),
(550984, 55779, 7467, '<td valign="top">Very nice, like the soft colors. What tiny pupil''s they have...</td>', 'Very nice, like the soft colors. What tiny pupil''s they have...', '2004-01-20 21:34:43.000000', NULL, 1),
(550986, 55643, 7467, '<td valign="top">I think I have seen this on a cover.... Nice pic.</td>', 'I think I have seen this on a cover.... Nice pic.', '2004-01-20 21:35:18.000000', NULL, 1),
(550989, 55471, 7467, '<td valign="top">Very nice, love the contrast. What shutter speed did you use? Other camera settings would also be of interest. I really like city skylines at night.</td>', 'Very nice, love the contrast. What shutter speed did you use? Other camera settings would also be of interest. I really like city skylines at night.', '2004-01-20 21:36:35.000000', NULL, 1),
(550994, 55759, 7467, '<td valign="top">Nice colors. Can''t really tell it is a tank of water! Very clear and sharp (from the subject back). Like the effect.</td>', 'Nice colors. Can''t really tell it is a tank of water! Very clear and sharp (from the subject back). Like the effect.', '2004-01-20 21:37:58.000000', NULL, 1),
(550995, 55819, 7467, '<td valign="top">Nice shot, maybe a slightly smaller F-Stop would have been the neck into focus also.</td>', 'Nice shot, maybe a slightly smaller F-Stop would have been the neck into focus also.', '2004-01-20 21:38:42.000000', NULL, 1),
(550996, 55815, 7467, '<td valign="top">Looks like crystals. Great colors and shapness... also like the glisten.</td>', 'Looks like crystals. Great colors and shapness... also like the glisten.', '2004-01-20 21:39:44.000000', NULL, 1),
(550997, 55523, 7467, '<td valign="top">Beautiful! Love the dark blue (must have used a polarizer). Very nice.</td>', 'Beautiful! Love the dark blue (must have used a polarizer). Very nice.', '2004-01-20 21:40:42.000000', NULL, 1),
(550999, 55706, 7467, '<td valign="top">Hope that is dried mud... not burned skin. Look like it is right out of NG. Nice. pic.</td>', 'Hope that is dried mud... not burned skin. Look like it is right out of NG. Nice. pic.', '2004-01-20 21:41:38.000000', NULL, 1),
(551000, 55567, 9581, '<td valign="top">This is a unique way of taking a picture of a cat! I like it a lot . Good quality!</td>', 'This is a unique way of taking a picture of a cat! I like it a lot . Good quality!', '2004-01-20 21:41:51.000000', NULL, 1),
(551002, 55640, 7467, '<td valign="top">Very nice and sharp. Great colors.</td>', 'Very nice and sharp. Great colors.', '2004-01-20 21:42:11.000000', NULL, 1),
(551004, 55402, 7467, '<td valign="top">Cool shot.. leterally.... Very nice.</td>', 'Cool shot.. leterally.... Very nice.', '2004-01-20 21:42:34.000000', NULL, 1),
(551006, 55789, 7467, '<td valign="top">Right off a NG cover....</td>', 'Right off a NG cover....', '2004-01-20 21:43:00.000000', NULL, 1),
(551009, 55218, 7467, '<td valign="top">Very nice... maybe a little lighter foreground... probably can''t do without over exposing the snow and clouds.</td>', 'Very nice... maybe a little lighter foreground... probably can''t do without over exposing the snow and clouds.', '2004-01-20 21:44:15.000000', NULL, 1),
(551012, 55359, 7467, '<td valign="top">Neat effect... like the colors... like it better now that I know it is not an oil sheen....</td>', 'Neat effect... like the colors... like it better now that I know it is not an oil sheen....', '2004-01-20 21:45:38.000000', NULL, 1),
(551014, 55574, 7467, '<td valign="top">Beautiful shot....love the sharpness and colors. Fits the theme very well.</td>', 'Beautiful shot....love the sharpness and colors. Fits the theme very well.', '2004-01-20 21:46:20.000000', NULL, 1),
(551016, 55360, 7467, '<td valign="top">I love these birds. They are very difficult to take a pic of. I have dozens of shots of Sandhill Cranes and Blue Herrons... very few from the front view.  They always walk away... don''t fly unless go get too close.</td>', 'I love these birds. They are very difficult to take a pic of. I have dozens of shots of Sandhill Cranes and Blue Herrons... very few from the front view.  They always walk away... don''t fly unless go get too close.', '2004-01-20 21:48:32.000000', NULL, 1),
(551017, 55782, 7467, '<td valign="top">Where is this tree located... when I was last in South Africa we went to Kruger... is this anywhere between Johannasburg and Kruger? Nice picture.</td>', 'Where is this tree located... when I was last in South Africa we went to Kruger... is this anywhere between Johannasburg and Kruger? Nice picture.', '2004-01-20 21:50:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(551018, 55788, 7467, '<td valign="top">OK what it it... cheeze I assume? or the top of a pie or pudding????? Like the texture, shadows and colors.</td>', 'OK what it it... cheeze I assume? or the top of a pie or pudding????? Like the texture, shadows and colors.', '2004-01-20 21:51:10.000000', NULL, 1),
(551020, 55045, 7467, '<td valign="top">Nice colors and texture.... background distracts a bit.</td>', 'Nice colors and texture.... background distracts a bit.', '2004-01-20 21:52:46.000000', NULL, 1),
(551035, 55752, 8624, '<td valign="top">fantastic animal portrait - full of personality! 10!</td>', 'fantastic animal portrait - full of personality! 10!', '2004-01-20 22:18:41.000000', NULL, 1),
(551037, 55399, 6477, '<td valign="top">Awesome pose. The only thing I don''t like very much is the sun light (the shadows), maybe in another time of the day would be better, but it is very natural and the model is superb...</td>', 'Awesome pose. The only thing I don''t like very much is the sun light (the shadows), maybe in another time of the day would be better, but it is very natural and the model is superb...', '2004-01-20 22:20:10.000000', NULL, 1),
(551038, 55541, 8624, '<td valign="top">I love the foggy breath</td>', 'I love the foggy breath', '2004-01-20 22:21:06.000000', NULL, 1),
(551040, 55694, 8624, '<td valign="top">great tones and lighting</td>', 'great tones and lighting', '2004-01-20 22:21:44.000000', NULL, 1),
(551041, 55790, 8624, '<td valign="top">beautiful. very mystical lighting</td>', 'beautiful. very mystical lighting', '2004-01-20 22:22:07.000000', NULL, 1),
(551043, 55777, 8624, '<td valign="top">I think this would have been a great portrait without the painterly effect. It still looks nice, but vould have been stronger.</td>', 'I think this would have been a great portrait without the painterly effect. It still looks nice, but vould have been stronger.', '2004-01-20 22:23:53.000000', NULL, 1),
(551059, 55499, 5822, '<td valign="top">Looks more like a Martian landscape to me as I think you''ve changed the color balance way too much and this looks highly unnatural.  Not a getaway I would want to escape to.</td>', 'Looks more like a Martian landscape to me as I think you''ve changed the color balance way too much and this looks highly unnatural.  Not a getaway I would want to escape to.', '2004-01-20 22:48:20.000000', NULL, 1),
(551066, 55671, 13390, '<td valign="top">I absolutely love this shot, very beautiful! The exposure is wonderful and the compostion near-flawless! Good luck on this very fine image!</td>', 'I absolutely love this shot, very beautiful! The exposure is wonderful and the compostion near-flawless! Good luck on this very fine image!', '2004-01-20 22:52:03.000000', NULL, 1),
(551069, 55523, 13390, '<td valign="top">When I first saw this one I said WOW. The lighting is absolutely marvelous and the exposure near-flawless.  I love the sky, a very strong and solid blue, love it, good luck!</td>', 'When I first saw this one I said WOW. The lighting is absolutely marvelous and the exposure near-flawless.  I love the sky, a very strong and solid blue, love it, good luck!', '2004-01-20 22:53:32.000000', NULL, 1),
(551075, 55756, 13390, '<td valign="top">I love this shot! I particularly enjoy the contrast between the shadow cast on the lion and the sunlight in it''s face (this is due to your wonderful lighting). I also believe that the trees in the background enhance this photo tremendously seems to fill the frame quite nicely. One thing that would add more strength IMO, is to equalize and balance the shot. I feel that the tree on the right mixed with the lion''s head tend to overdominate the shot. It just feels ever so slightly heavy on the right. But this is a very, very minor thing and the rest of the elements more than make up for that fact.</td>', 'I love this shot! I particularly enjoy the contrast between the shadow cast on the lion and the sunlight in it''s face (this is due to your wonderful lighting). I also believe that the trees in the background enhance this photo tremendously seems to fill the frame quite nicely. One thing that would add more strength IMO, is to equalize and balance the shot. I feel that the tree on the right mixed with the lion''s head tend to overdominate the shot. It just feels ever so slightly heavy on the right. But this is a very, very minor thing and the rest of the elements more than make up for that fact.', '2004-01-20 22:57:18.000000', NULL, 1),
(551076, 55694, 13390, '<td valign="top">I have had this shot on my mind a lot lately. It is an extrmely unique shot, which fits the NG theme extremely well. It must have been extremely windy for the snow to be piled up on the trees in that way. There''s just something to this shot, I can''t quite put my finger on it, but it is truly marvelous. Good luck!</td>', 'I have had this shot on my mind a lot lately. It is an extrmely unique shot, which fits the NG theme extremely well. It must have been extremely windy for the snow to be piled up on the trees in that way. There''s just something to this shot, I can''t quite put my finger on it, but it is truly marvelous. Good luck!', '2004-01-20 22:59:30.000000', NULL, 1),
(551080, 55218, 5822, '<td valign="top">This would be a winner in POV and I wouldn''t be surprised if it took a ribbon in this challenge. Wonderful photo! I love the silhouetted trees against the muted colors and that you can see, it seems, for miles and miles. Only thing that needs improving is that the distant mountains get lost in the same colored clouds.</td>', 'This would be a winner in POV and I wouldn''t be surprised if it took a ribbon in this challenge. Wonderful photo! I love the silhouetted trees against the muted colors and that you can see, it seems, for miles and miles. Only thing that needs improving is that the distant mountains get lost in the same colored clouds.', '2004-01-20 23:02:11.000000', NULL, 1),
(551082, 55249, 5822, '<td valign="top">Beautiful shot but I think I would have liked to have seen a bit more rock to balance it out. Very nice though.</td>', 'Beautiful shot but I think I would have liked to have seen a bit more rock to balance it out. Very nice though.', '2004-01-20 23:05:52.000000', NULL, 1),
(551099, 55114, 5822, '<td valign="top">Cropping is a little tight around the animal. I really like the muted colors and think it''s very appropo of NG. Good photojounalistic pic. Good job!</td>', 'Cropping is a little tight around the animal. I really like the muted colors and think it''s very appropo of NG. Good photojounalistic pic. Good job!', '2004-01-20 23:18:23.000000', NULL, 1),
(551107, 55705, 5822, '<td valign="top">This is a really nice photo. You''re exposure is right on, despite shooting into the sun and focus is good as well as the simple composition. I just wish it were titled differently.</td>', 'This is a really nice photo. You''re exposure is right on, despite shooting into the sun and focus is good as well as the simple composition. I just wish it were titled differently.', '2004-01-20 23:25:24.000000', NULL, 1),
(551109, 55614, 6943, '<td valign="top">Really like the subtle colors and angle of this photo. Was it a tough hike to this spot in the cold? Just my opinion, but I would crop (or clone out) the tiny piece of the tree that snuck into the upper right hand corner of the photo. Nice shot.</td>', 'Really like the subtle colors and angle of this photo. Was it a tough hike to this spot in the cold? Just my opinion, but I would crop (or clone out) the tiny piece of the tree that snuck into the upper right hand corner of the photo. Nice shot.', '2004-01-20 23:27:06.000000', NULL, 1),
(551112, 55790, 6943, '<td valign="top">I like the mood this photo conveys, takes you back in time. Also like your choice to make this photo \"soft\". Don''t know if it is necessarily National Geographic-ish photo but really like it none the less.</td>', 'I like the mood this photo conveys, takes you back in time. Also like your choice to make this photo \"soft\". Don''t know if it is necessarily National Geographic-ish photo but really like it none the less.', '2004-01-20 23:30:12.000000', NULL, 1),
(551113, 55752, 6943, '<td valign="top">Like how you filled the frame with this shot, maybe add a little more sharpening to bring out the hair? Nice shot.</td>', 'Like how you filled the frame with this shot, maybe add a little more sharpening to bring out the hair? Nice shot.', '2004-01-20 23:31:25.000000', NULL, 1),
(551127, 55707, 6600, '<td valign="top">Nice macro shot. Well exposed.  I can see this in National Geographic, nice job!</td>', 'Nice macro shot. Well exposed.  I can see this in National Geographic, nice job!', '2004-01-20 23:45:54.000000', NULL, 1),
(551129, 55776, 6600, '<td valign="top">Certainly fits the challenge.  Nice job!</td>', 'Certainly fits the challenge.  Nice job!', '2004-01-20 23:46:42.000000', NULL, 1),
(551131, 55671, 6600, '<td valign="top">Well composed and exposed. Nice water action, looks like a neat place.  Good job!</td>', 'Well composed and exposed. Nice water action, looks like a neat place.  Good job!', '2004-01-20 23:48:47.000000', NULL, 1),
(551140, 55752, 6600, '<td valign="top">I just love these animals (what a look!).  Nice composition, not tack sharp, none the less still a nice photo.  Good Job.</td>', 'I just love these animals (what a look!).  Nice composition, not tack sharp, none the less still a nice photo.  Good Job.', '2004-01-20 23:54:21.000000', NULL, 1),
(551303, 55756, 10848, '<td valign="top">Outstanding, great angle in which you captured this shot, the open mouth as if roaring was a great capture 10</td>', 'Outstanding, great angle in which you captured this shot, the open mouth as if roaring was a great capture 10', '2004-01-21 01:52:32.000000', NULL, 1),
(551309, 55819, 10848, '<td valign="top">This is a great shot, wonderful dof, detail great 10</td>', 'This is a great shot, wonderful dof, detail great 10', '2004-01-21 01:54:11.000000', NULL, 1),
