(553665, 55765, 16352, '<td valign="top">just seems to need to be a bit more "contrasty" to bring out that "winter, cold" feel</td>', 'just seems to need to be a bit more "contrasty" to bring out that "winter, cold" feel', '2004-01-22 14:53:19.000000', NULL, 1),
(553668, 55316, 16352, '<td valign="top">That water looks "CRYSTAL BLACK" it is beautiful.<br/>LOVE IT I would have scored it 10 if that bright area at the bottom was cropped out</td>', 'That water looks "CRYSTAL BLACK" it is beautiful.LOVE IT I would have scored it 10 if that bright area at the bottom was cropped out', '2004-01-22 14:54:54.000000', NULL, 1),
