INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(556463, 55640, 1128, '<td valign="top">gorgeous underwater shot.  It''s so clear and the lighting is terrific.  I feel like I can touch those fish on my screen!   great job</td>', 'gorgeous underwater shot.  It''s so clear and the lighting is terrific.  I feel like I can touch those fish on my screen!   great job', '2004-01-25 18:53:12.000000', NULL, 1),
(556465, 55680, 2158, '<td valign="top">Beautiful picture, but it would really look better (in my opinion) without all that noise.</td>', 'Beautiful picture, but it would really look better (in my opinion) without all that noise.', '2004-01-25 18:58:07.000000', NULL, 1),
(556467, 55694, 8860, '<td valign="top">Very surreal lighting. Bright spot is a little hot and ''alien'' but it''s a great scene.</td>', 'Very surreal lighting. Bright spot is a little hot and ''alien'' but it''s a great scene.', '2004-01-25 19:02:33.000000', NULL, 1),
(556468, 55807, 8860, '<td valign="top">This is a lovely scene with some great texture on the ground. The sky hot spot is just too overexposed, but the shot survives it.</td>', 'This is a lovely scene with some great texture on the ground. The sky hot spot is just too overexposed, but the shot survives it.', '2004-01-25 19:04:19.000000', NULL, 1),
(556501, 55574, 8637, '<td valign="top">Very regal...well done.  Like the pose...little more sparkle in the eyes would be nice...but not always possible.</td>', 'Very regal...well done.  Like the pose...little more sparkle in the eyes would be nice...but not always possible.', '2004-01-25 19:44:57.000000', NULL, 1),
(556502, 55814, 8637, '<td valign="top">excellent angle...background is almost too bright...looks like the tip of the nose is little fuzzy.</td>', 'excellent angle...background is almost too bright...looks like the tip of the nose is little fuzzy.', '2004-01-25 19:46:19.000000', NULL, 1),
(556503, 55640, 8637, '<td valign="top">Beautiful underwater shot...bet this wasn''t done on the first try!</td>', 'Beautiful underwater shot...bet this wasn''t done on the first try!', '2004-01-25 19:47:11.000000', NULL, 1),
(556506, 55718, 8637, '<td valign="top">Seems that they could be a little sharper...little soft.  Nice shot though and neat objects.</td>', 'Seems that they could be a little sharper...little soft.  Nice shot though and neat objects.', '2004-01-25 19:48:32.000000', NULL, 1),
(556511, 55114, 8637, '<td valign="top">Close up on the head might have been better...or not cut top of back out.</td>', 'Close up on the head might have been better...or not cut top of back out.', '2004-01-25 19:50:38.000000', NULL, 1),
(556517, 55420, 8637, '<td valign="top">Very nice feel to this shot...the colors, DOF, cropping all are perfect!  Little more expression in the eyes, with a little more reflection would have helped...but not always possible.</td>', 'Very nice feel to this shot...the colors, DOF, cropping all are perfect!  Little more expression in the eyes, with a little more reflection would have helped...but not always possible.', '2004-01-25 19:53:21.000000', NULL, 1),
(556521, 55804, 8637, '<td valign="top">Little speck on image could have been removed.  And might have chosen a more contrasty background...but I''m not very good about these myself.</td>', 'Little speck on image could have been removed.  And might have chosen a more contrasty background...but I''m not very good about these myself.', '2004-01-25 19:57:10.000000', NULL, 1),
(556525, 55775, 8637, '<td valign="top">Nice setting and angle, but too soft and DOF seems little narrow...may just be out of focus?  More light to bring out the colors would help...neat plant though.</td>', 'Nice setting and angle, but too soft and DOF seems little narrow...may just be out of focus?  More light to bring out the colors would help...neat plant though.', '2004-01-25 20:00:17.000000', NULL, 1),
(556527, 55399, 8637, '<td valign="top">Closer view of the head would have been better since the feet were not included.  Great colors and sharp image.</td>', 'Closer view of the head would have been better since the feet were not included.  Great colors and sharp image.', '2004-01-25 20:01:28.000000', NULL, 1),
(556528, 55717, 8637, '<td valign="top">The branch in front of the parrot really distracts from the shot...nice capture though and great colors.</td>', 'The branch in front of the parrot really distracts from the shot...nice capture though and great colors.', '2004-01-25 20:02:38.000000', NULL, 1),
(556529, 55360, 8637, '<td valign="top">Nice idea...would have been better to get a frontal shot..I tried to capture these at Aransas last year though and understand why you get lots of shots of that facing the other way.  I''m glad you used the Nat''l Geographic border...I thought more would.</td>', 'Nice idea...would have been better to get a frontal shot..I tried to capture these at Aransas last year though and understand why you get lots of shots of that facing the other way.  I''m glad you used the Nat''l Geographic border...I thought more would.', '2004-01-25 20:04:10.000000', NULL, 1),
(556531, 55629, 8637, '<td valign="top">Beautiful colors...but for geographic believe a frontal shot would have been better.  Can''t get over those wonderful colors though!</td>', 'Beautiful colors...but for geographic believe a frontal shot would have been better.  Can''t get over those wonderful colors though!', '2004-01-25 20:06:20.000000', NULL, 1),
(556533, 55564, 8637, '<td valign="top">Little too dark around the head.</td>', 'Little too dark around the head.', '2004-01-25 20:06:43.000000', NULL, 1),
(556534, 55642, 8637, '<td valign="top">For Mardi Gras really need the colors...</td>', 'For Mardi Gras really need the colors...', '2004-01-25 20:07:03.000000', NULL, 1),
(556535, 55819, 8637, '<td valign="top">Great reflection in the eyes.</td>', 'Great reflection in the eyes.', '2004-01-25 20:08:11.000000', NULL, 1),
(556536, 55738, 8637, '<td valign="top">Wonderfull...great tutorial on lighting.</td>', 'Wonderfull...great tutorial on lighting.', '2004-01-25 20:09:15.000000', NULL, 1),
(556538, 55790, 8637, '<td valign="top">Great still life...not sure it would make a Nat''l Geographic cover...but you should sell a lot of photos on DPC!</td>', 'Great still life...not sure it would make a Nat''l Geographic cover...but you should sell a lot of photos on DPC!', '2004-01-25 20:10:13.000000', NULL, 1),
(556543, 55683, 7543, '<td valign="top">Good composition, good eye. Only thing bothering me is too much grain for this type of shot (seems like the light was good)</td>', 'Good composition, good eye. Only thing bothering me is too much grain for this type of shot (seems like the light was good)', '2004-01-25 20:24:49.000000', NULL, 1),
(556544, 55507, 7543, '<td valign="top">Great choice of shutter time! (Probably the best example I''ve seen) Nice effect</td>', 'Great choice of shutter time! (Probably the best example I''ve seen) Nice effect', '2004-01-25 20:26:36.000000', NULL, 1),
(556546, 55242, 7543, '<td valign="top">Technically flawless! (L-glass?) Beautiful colors and DOF.</td>', 'Technically flawless! (L-glass?) Beautiful colors and DOF.', '2004-01-25 20:28:37.000000', NULL, 1),
(556547, 55807, 7543, '<td valign="top">Beautiful shot, I would want this one on my wall (and there arent many shots that I would want on my wall). Great angle, great subjects and the sky is just amazing on top of everything else. Perfect shot, my only 10 this week (up to now at least)</td>', 'Beautiful shot, I would want this one on my wall (and there arent many shots that I would want on my wall). Great angle, great subjects and the sky is just amazing on top of everything else. Perfect shot, my only 10 this week (up to now at least)', '2004-01-25 20:32:23.000000', NULL, 1),
(556548, 55790, 7543, '<td valign="top">Technically flawless, good job on editing</td>', 'Technically flawless, good job on editing', '2004-01-25 20:33:07.000000', NULL, 1),
(556549, 55629, 7543, '<td valign="top">Good shot, love the composition. A bit warm coloring, but nothing bad. Makes you feel like you are in England on the countryside. Good job.</td>', 'Good shot, love the composition. A bit warm coloring, but nothing bad. Makes you feel like you are in England on the countryside. Good job.', '2004-01-25 20:34:51.000000', NULL, 1),
