(556570, 55507, 15189, '<td valign="top">When I think National Geographic, I think color.  Although this shot is not in color, I like your message and the technical quality of the photo.  Great execution of a good idea!</td>', 'When I think National Geographic, I think color.  Although this shot is not in color, I like your message and the technical quality of the photo.  Great execution of a good idea!', '2004-01-25 20:53:25.000000', NULL, 1),
(556571, 55790, 15189, '<td valign="top">Very nice use of soft focus and lighting.  Good job!</td>', 'Very nice use of soft focus and lighting.  Good job!', '2004-01-25 20:54:12.000000', NULL, 1),
(556572, 55522, 15189, '<td valign="top">Brrrrrr... Great shot!  Color, exposure and composition all wonderful.  Good Job, a ten from me.</td>', 'Brrrrrr... Great shot!  Color, exposure and composition all wonderful.  Good Job, a ten from me.', '2004-01-25 20:55:36.000000', NULL, 1),
