(556575, 55045, 15189, '<td valign="top">Fence in the back is a bit distracting, maybe a shallower DOF.  Also the tail seems more in focus than the eyes.  Exposure is great, especially in the presence of snow.  Overall, good job!</td>', 'Fence in the back is a bit distracting, maybe a shallower DOF.  Also the tail seems more in focus than the eyes.  Exposure is great, especially in the presence of snow.  Overall, good job!', '2004-01-25 20:59:59.000000', NULL, 1),
(556576, 55666, 15189, '<td valign="top">When I think NG, I think of vibrant color.  In spite of that, this is a wonderful shot.  Good exposure and composition.  Very nice idea, executed perfectly.</td>', 'When I think NG, I think of vibrant color.  In spite of that, this is a wonderful shot.  Good exposure and composition.  Very nice idea, executed perfectly.', '2004-01-25 21:02:18.000000', NULL, 1),
